drop table if exists quiz_characters;

create table if not exists quiz_characters (
    last_name varchar2(50),
    title     varchar2(20)
)
/ 

insert into quiz_characters
values ('Moriarty', 'Professor'), ('Holmes', 'Detective'), ('Watson', 'Doctor')
/

commit;

alter session set sql_transpiler = on;


