create or replace function quiz_format_title(
    p_name in varchar2,
    p_title in varchar2
) return varchar2
is
    function prefixed(
        p_value in varchar2,
        p_prefix in varchar2
    ) return varchar2
    is
    begin
        return trim(p_prefix || ' ' || p_value);
    end prefixed;

begin
    return prefixed(p_name, initcap(p_title));
end quiz_format_title;
/

