create or replace function quiz_format_title(
    p_name in varchar2,
    p_title in varchar2
) return varchar2
is
    l_result varchar2(100);
begin
    l_result := 
        case 
            when p_title <> initcap(p_title) then initcap(p_title)
            else p_title 
        end;

    l_result := l_result || case when l_result is not null then ' ' end || p_name;
    l_result := trim(l_result);
    return l_result;
end quiz_format_title;
/

